  /** Đánh giá 1 điều kiện "Lọc nâng cao" trên 1 dòng (operator = MÃ ổn định của hrm-filter-panel). */
  matchCond(c, cond) {
    const op = cond.operator;
    const v = cond.value;
    switch (cond.key) {
      case "nld": {
        const nv = insNhanVien(c.nhanVienId);
        return this.matchText(`${nv?.name ?? ""} ${nv?.code ?? ""}`.toLowerCase(), op, String(v ?? "").toLowerCase());
      }
      case "donVi":
        return this.matchEq(c.donViId, op, v);
      case "ky":
        return this.matchEq(c.kyTacDong, op, v);
      case "pa":
        return this.matchEq(c.maPhuongAn ?? "", op, v);
      case "nhom":
        return this.matchMulti(c.nhomNgoaiLe, op, v);
      case "hieuLuc":
        return this.matchDate(c.ngayHieuLuc, op, v);
      case "phanLoai":
        return true;
      // NO-OP ở baseChanges (giữ classCounts đúng) — lọc class thật áp ở filteredChanges.
      default:
        return true;
    }
  }
  matchText(hay, op, needle) {
    if (op === "empty")
      return hay.trim() === "";
    if (op === "notEmpty")
      return hay.trim() !== "";
    if (op === "notContains")
      return !hay.includes(needle);
    if (op === "startsWith")
      return hay.startsWith(needle);
    return hay.includes(needle);
  }
  matchEq(field, op, v) {
    if (op === "empty")
      return !field;
    if (op === "notEmpty")
      return !!field;
    const val = v == null ? "" : String(v);
    return op === "isNot" ? field !== val : field === val;
  }
  matchMulti(groups, op, v) {
    if (op === "empty")
      return groups.length === 0;
    if (op === "notEmpty")
      return groups.length > 0;
    const sel = Array.isArray(v) ? v.map(String) : [];
    if (!sel.length)
      return true;
    const hit = groups.some((g) => sel.includes(g));
    return op === "notIn" ? !hit : hit;
  }
  matchDate(dateStr, op, v) {
    const d2 = insParseVnDate(dateStr);
    if (!d2)
      return false;
    if (op === "onOrAfter") {
      const a = insToDate(v);
      return !a || d2.getTime() >= a.getTime();
    }
    if (op === "before") {
      const b = insToDate(v);
      return !b || d2.getTime() < b.getTime();
    }
    if (Array.isArray(v) && v.length === 2) {
      const a = insToDate(v[0]);
      const b = insToDate(v[1]);
      if (a && d2.getTime() < a.getTime())
        return false;
      if (b && d2.getTime() > b.getTime())
        return false;
    }
    return true;
  }
