  /** Nút hành động theo dòng: "Xác nhận" (san-sang → vào lô ngay, ở lại lưới) / "Bổ sung" (mở panel). */
  onPrimary(row, e) {
    e?.stopPropagation();
    if (row.primaryKind === "confirm") {
      const r = this.store.bulkChuyenLo([row.id]);
      if (r.done && r.loBatchId) {
        const kyLabel = insKy(r.ky ?? "")?.label ?? "";
        this.msg.success(`\u2713 \u0110\xE3 x\xE1c nh\u1EADn ${row.ten}${kyLabel ? " \xB7 " + kyLabel : ""} \xB7 \u0110\u1EE3t #${r.loBatchId.slice(8)}`);
      } else if (r.daXacNhan) {
        const c = this.store.change(row.id);
        this.msg.warning(`\u2713 \u0110\xE3 x\xE1c nh\u1EADn \xB7 \u26A0 ch\u01B0a x\u1EBFp \u0111\u1EE3t: ${c?.lyDoChuaXepDuoc ?? "xem chi ti\u1EBFt"}`);
        this.openById(row.id);
      } else {
        const p = this.store.chuyenLoPreview([row.id]);
        this.msg.warning(p.blocked[0]?.reason ?? "Ch\u01B0a \u0111\u1EE7 \u0111i\u1EC1u ki\u1EC7n x\xE1c nh\u1EADn \u2014 m\u1EDF chi ti\u1EBFt \u0111\u1EC3 xem.");
        this.openById(row.id);
      }
    } else if (row.primaryKind === "supplement" || row.primaryKind === "review") {
      this.openById(row.id);
    }
  }
