function sourceIconOf(k) {
  switch (k) {
    case "employee":
      return User;
    case "contract":
      return FileText;
    case "payroll":
      return Coin;
    case "decision":
      return FileCheck;
    case "attendance":
      return CalendarTime;
    case "declaration":
      return Send;
    case "benefit":
      return HeartHandshake;
    default:
      return FileText;
  }
}
